unsigned RDL_getNofRingsystems(const RDL_data* data)
{
  if (!data) {
    RDL_outputFunc(RDL_ERROR, "RDL_data is NULL!\n");
    return RDL_INVALID_RESULT;
  }

  return data->bccGraphs->nof_bcc;
}
