47	  unsigned q_head, q_nextfree, q_size;
48	  char *color = malloc(gra->V * sizeof(*color));
49	  unsigned *queue = malloc(gra->V * sizeof(*queue));
50	
51	  for(run=1; run<3; ++run) /*2 run throughs to get Vr correct*/
52	  {
53	    for(i=0; i<gra->V; ++i)
54	    {
55	      /*initialization*/
56	      q_head=0;
57	      q_nextfree=0;
58	      q_size=0;
59	      for(j=0; j<gra->V; ++j)
60	      {
61	        if(run==1)
62	        {
63	          spi->dist[i][j] = INFINITY;
64	          spi->pred[i][j] = INFINITY;
65	          spi->reachable[i][j] = 0;
66	        }
67	        color[j] = 'w'; /*white*/
68	      }
69	      spi->dist[i][i] = 0;
70	      spi->pred[i][i] = i;
71	      color[i] = 'b'; /*black*/
72	      queue[q_nextfree]=i; /*enqueue*/
73	      ++q_nextfree; /*enqueue*/
74	      ++q_size; /*enqueue*/
75	
76	      while(q_size > 0)
77	      {
78	        w = queue[q_head]; /*deqeue*/
79	        ++q_head; /*dequeue*/
80	        --q_size; /*dequeue*/
81	        for(adj=0; adj<gra->degree[w]; ++adj) /*for each node adj to w*/
82	        {
83	          j=gra->adjList[w][adj][0];
84	          /*if j precedes i in order (only first run)*/
85	          if(run==2 || ((gra->degree[j] == gra->degree[i]) && j<i) ||
86	          gra->degree[j] < gra->degree[i])
87	          if(color[j] == 'w') /*unvisited*/
88	          {
89	            if(run==2)
90	            {/*if in the 2nd run a dist gets shorter*/
91	              if(spi->dist[i][w]+1 < spi->dist[i][j])
92	              {/*not element of Vr*/
93	                spi->reachable[i][j] = 0;
94	              }
95	            }
96	            if(run==1 || (spi->dist[i][w]+1 < spi->dist[i][j]))
97	            {/*if 2nd run and dist stays the same, pred shouldn't
98	            change to keep the shortest path along ordering*/
99	              /*predecessor of j on a shortest path from i to j*/
100	              spi->pred[i][j] = w;
101	            }
102	            if(spi->dist[i][j] > spi->dist[i][w]+1)
103	            {
104	              spi->dist[i][j] = spi->dist[i][w] + 1;
105	            }
106	            color[j] = 'b';
107	            queue[q_nextfree] = j; /*enqueue*/
108	            ++q_nextfree; /*enqueue*/
109	            ++q_size; /*enqueue*/
110	            if(run==1)
111	            {/*reachable should not change to 1 in the 2nd run*/
112	              spi->reachable[i][j] = 1;
113	            }
114	          }
115	        }
116	      }
117	    }
118	  }
119	
120	  free(color);
121	  free(queue);
122	}
