49: RDL_DimacsGraph* RDL_dimacsGraph_read(const char* filename)
50: {
51:   FILE* infile;
52:   RDL_DimacsGraph* graph = NULL;
53:   char line[RDL_MAXSIZE + 1];
54:   unsigned node1, node2, ring;
55:   int error = 0;
56:   int stage = 0;
57:   unsigned edge_counter = 0;
58:   unsigned ring_counter = 0;
59:   unsigned ring_position_counter = 0;
60:   unsigned last_ring = 0;
61:   unsigned ring_size = 0;
62:   unsigned ring_idx, edge_idx;
63:   unsigned eidx;
64:   int found_eidx = -1;
65:   int read_initializer = -1;
66:   unsigned len;
67:   RDL_edge edge;
68: 
69:   infile = fopen(filename, "r");
70: 
71:   if (!infile) {
72:     return graph;
73:   }
74: 
75:   graph = malloc(sizeof(*graph));
76:   graph->nof_cycles = 0;
77:   graph->edges = NULL;
78:   graph->cycles = NULL;
79:   graph->sorted_cycles = NULL;
80:   graph->name = NULL;
81: 
82:   while (fgets(line, RDL_MAXSIZE, infile) && !error) {
83:     if (line[0] == 'p') {
84:       if (!stage) {
85:         stage = 1;
86: 
87:         read_initializer = sscanf(line, "p edge %u %u %u", &graph->nof_nodes, &graph->nof_edges, &graph->nof_cycles);
88:         if (read_initializer == 3) {
89:           graph->edges = malloc(graph->nof_edges * sizeof(*graph->edges));
90:           graph->cycles = malloc(graph->nof_cycles * sizeof(*graph->cycles));
91:           memset(graph->cycles, 0, graph->nof_cycles * sizeof(*graph->cycles));
92:         }
93:         else if (read_initializer == 2) {
94:           graph->edges = malloc(graph->nof_edges * sizeof(*graph->edges));
95:           graph->nof_cycles = UINT_MAX;
96:           graph->cycles = NULL;
97:         }
98:         else {
99:           RDL_outputFunc(RDL_ERROR, "invalid line starting with 'p'\n");
100:           error = 1;
101:         }
102:       }
103:       else {
104:         RDL_outputFunc(RDL_ERROR, "duplicate 'p' line found!\n");
105:         error = 1;
106:       }
107:     }
108:     else if (line[0] == 'e') {
109:       if (stage != 1) {
110:         RDL_outputFunc(RDL_ERROR, "edge 'e' found without 'p' definition!\n");
111:         error = 1;
112:       }
113:       else {
114:         if (!sscanf(line, "e %u %u", &node1, &node2)) {
115:           RDL_outputFunc(RDL_ERROR, "invalid edge specification line\n");
116:           error = 1;
117:         }
118:         else if (edge_counter == graph->nof_edges) {
119:           RDL_outputFunc(RDL_ERROR, "too many edges found!\n");
120:           error = 1;
121:         }
122:         else if (node1 < 1 || node1 > graph->nof_nodes || node2 < 1 || node2 > graph->nof_nodes) {
123:           RDL_outputFunc(RDL_ERROR, "illegal edge specification!\n");
124:           error = 1;
125:         }
126:         else {
127:           graph->edges[edge_counter][0] = node1;
128:           graph->edges[edge_counter][1] = node2;
129:           ++edge_counter;
130:         }
131:       }
132:     }
133:     else if (line[0] == 'r') {
134:       if (!stage) {
135:         RDL_outputFunc(RDL_ERROR, "ring 'r' found without 'p' definition!\n");
136:         error = 1;
137:       }
138:       else if (!graph->cycles) {
139:         RDL_outputFunc(RDL_ERROR, "ring 'r' found without 'p' definition for rings!\n");
140:         error = 1;
141:       }
142:       else {
143:         stage = 2;
144:         if (sscanf(line, "r %u %u %u %u", &ring, &ring_size, &node1, &node2) != 4) {
145:           RDL_outputFunc(RDL_ERROR, "invalid ring specification line\n");
146:           error = 1;
147:         }
148:         else if (ring < 1|| ring > graph->nof_cycles) {
149:           RDL_outputFunc(RDL_ERROR, "invalid ring counter '%u'!\n", ring);
150:           error = 1;
151:         }
152:         else if (node1 < 1 || node1 > graph->nof_nodes || node2 < 1 || node2 > graph->nof_nodes) {
153:           RDL_outputFunc(RDL_ERROR, "illegal edge specification!\n");
154:           error = 1;
155:         }
156:         else {
157:           if (ring != last_ring) {
158:             if (last_ring) {
159:               if (ring_position_counter != graph->cycles[last_ring-1]->weight) {
160:                 RDL_outputFunc(RDL_ERROR, "last ring %u wasn't filled up!\n", last_ring);
161:                 error = 1;
162:               }
163:               else if (ring != last_ring + 1) {
164:                 RDL_outputFunc(RDL_ERROR, "rings have to be continuous, '%u' follows on '%u'", ring, last_ring);
165:                 error = 1;
166:               }
167:             }
168: 
169:             ring_position_counter = 0;
170:             graph->cycles[ring-1] = malloc(sizeof(**graph->cycles));
171:             graph->cycles[ring-1]->weight = ring_size;
172:             graph->cycles[ring-1]->edges = malloc(ring_size * sizeof(*graph->cycles[ring-1]->edges));
173:             last_ring = ring;
174:             ++ring_counter;
175:           }
176: 
177:           if (ring_position_counter == graph->cycles[ring-1]->weight) {
178:             RDL_outputFunc(RDL_ERROR, "too many edges for ring!\n");
179:             error = 1;
180:           }
181:           else {
182:             graph->cycles[ring-1]->edges[ring_position_counter][0] = node1;
183:             graph->cycles[ring-1]->edges[ring_position_counter][1] = node2;
184:             ++ring_position_counter;
185:           }
186:         }
187:       }
188:     }
189:     else if (line[0] == 'c') {
190:       len = strlen(line);
191:       if (!graph->name && len > 3) {
192:         /* skip first two characters (but reserve +1 for \0 and -1 for the newline) */
193:         graph->name = malloc((len - 2) * sizeof(*graph->name));
194:         strncpy(graph->name, line + 2, len - 3);
195:         graph->name[len - 3] = '\0';
196:       }
197:     }
198:     else {
199:       RDL_outputFunc(RDL_ERROR, "invalid line!\n");
200:       error = 1;
201:     }
202:   }
203: 
204:   if (!error && graph->nof_cycles != UINT_MAX) {
205:     if (ring_counter != graph->nof_cycles) {
206:       RDL_outputFunc(RDL_ERROR, "mismatch between number of cycles!\n");
207:       error = 1;
208:     }
209: 
210:     if (last_ring) {
211:       if (ring_position_counter != graph->cycles[last_ring-1]->weight) {
212:         RDL_outputFunc(RDL_ERROR, "last ring %u wasn't filled up!\n", last_ring);
213:         error = 1;
214:       }
215:     }
216:   }
217: 
218:   if (!error && edge_counter != graph->nof_edges) {
219:     RDL_outputFunc(RDL_ERROR, "mismatch between number of edges!\n");
220:     error = 1;
221:   }
222: 
223:   if (error && graph) {
224:     RDL_dimacsGraph_delete(graph);
225:     graph = NULL;
226:   }
227: 
228:   fclose(infile);
229: 
230:   if (!error) {
231:     if (graph->cycles) {
232:       graph->sorted_cycles = malloc(graph->nof_cycles * sizeof(*graph->sorted_cycles));
233:       for (ring_idx = 0; ring_idx < graph->nof_cycles; ++ring_idx) {
234:         graph->sorted_cycles[ring_idx] = malloc((graph->nof_edges + 1) * sizeof(**graph->sorted_cycles));
235:         memset(graph->sorted_cycles[ring_idx], 0, graph->nof_edges * sizeof(**graph->sorted_cycles));
236:         graph->sorted_cycles[ring_idx][graph->nof_edges] = 2;
237:         for (edge_idx = 0; edge_idx < graph->cycles[ring_idx]->weight; ++edge_idx) {
238:           edge[0] = graph->cycles[ring_idx]->edges[edge_idx][0];
239:           edge[1] = graph->cycles[ring_idx]->edges[edge_idx][1];
240:           for (eidx = 0; eidx < graph->nof_edges; ++eidx) {
241:             if ((graph->edges[eidx][0] == edge[0]&& graph->edges[eidx][1] == edge[1])
242:                 || (graph->edges[eidx][0] == edge[1] && graph->edges[eidx][1] == edge[0])) {
243:               found_eidx = eidx;
244:             }
245:           }
246:           graph->sorted_cycles[ring_idx][found_eidx] = 1;
247:         }
248:       }
249: 
250:       qsort(graph->sorted_cycles, graph->nof_cycles, sizeof(*graph->sorted_cycles), RDL_cmp_cycles);
251:     }
252:     else {
253:       graph->sorted_cycles = NULL;
254:     }
255:   }
256: 
257:   return graph;
258: }

